css:
/* ========== CONFIGURACIÓN GLOBAL ========== */
* {
    font-family: Arial, sans-serif;
    font-size: 12px;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body.print-format {
    background: white;
    color: #000;
}

/* ========== CONTENEDOR PRINCIPAL ========== */
.print-format-container {
    margin: 10px;
    max-width: 100%;
}

/* ========== HEADER ========== */
#information-table {
    width: 100%;
    border: none;
    margin-bottom: 10px;
}

#information-table td {
    vertical-align: middle;
    border: none !important;
    padding: 5px !important;
}

/* Logo */
.logo {
    display: flex;
    justify-content: center;
    align-items: center;
}

.logo img {
    max-height: 90px;
    width: auto;
    height: auto;
    max-width: 100%;
    display: block;
}

/* ========== TIPOGRAFÍA ========== */
h3 {
    font-size: 16px;
    font-weight: bold;
    margin: 4px 0;
    color: #000;
}

h4 {
    font-size: 14px;
    font-weight: bold;
    margin: 8px 0 4px 0;
    color: #000;
}

h5 {
    font-size: 13px;
    font-weight: bold;
    margin: 6px 0 4px 0;
    color: #000;
}

p {
    margin: 4px 0;
    line-height: 1.4;
    text-align: justify;
}

/* ========== TABLAS ========== */
table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
}

th, td {
    border: 1px solid #000;
    padding: 4px 6px;
    font-size: 11px;
    line-height: 1.3;
    vertical-align: top;
}

th {
    font-weight: bold;
    background-color: #f5f5f5;
}

/* Tabla principal sin bordes internos */
table.main-table,
table.main-table td,
table.main-table th {
    border: none !important;
}

/* Tabla de información de paciente */
.main-table td {
    border: none !important;
    padding: 4px 6px !important;
    text-align: left !important;
}

.main-table td.header {
    width: 30%;
}

.main-table td.information {
    width: 70%;
}
.datos-paciente {
  margin-top: 15px;
  border-top: 2px solid #000;
}
.encounter-data {
  margin-top: 15px;
  border-top: 2px solid #000;
}
/* ========== CONTROL DE SALTOS DE PÁGINA ========== */
table.main-table,
.datos-generales,
.footer {
    page-break-inside: avoid;
}

tr {
    page-break-inside: avoid;
}

tbody {
    page-break-inside: auto;
}

h3, h4, h5 {
    page-break-after: avoid;
}

/* ========== MEDIA QUERIES PARA IMPRESIÓN ========== */
@media print {
    body.print-format {
        margin: 0;
        padding: 0;
    }
    
    .print-format-container {
        margin: 8mm;
    }
    
    * {
        font-size: 11px;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    
    .logo img {
        max-height: 75px;
    }
    
    h3 {
        font-size: 15px;
    }
    
    h4 {
        font-size: 13px;
    }
    
    h5 {
        font-size: 12px;
    }
    
    th, td {
        font-size: 10px !important;
        padding: 2px 4px !important;
    }
    
    #table-info td {
        padding: 2px 4px !important;
    }
    
    /* Evitar huérfanas y viudas */
    p, td, th {
        orphans: 3;
        widows: 3;
    }
}

/* ========== MEDIA QUERY PARA LANDSCAPE ========== */
@media print and (orientation: landscape) {
    .logo img {
        max-height: 100px;
    }
    
    .print-format-container {
        margin: 10mm 15mm;
    }
}
